'use strict';
function v12WeatherName(code){const c=Number(code);if(code==null||!Number.isFinite(c))return '天气未取得';if(c===0)return '晴';if(c===1)return '以晴为主';if(c===2)return '局部多云';if(c===3)return '阴';if(c===45||c===48)return '雾';if([51,53,55,56,57].includes(c))return '毛毛雨';if([61,63,65].includes(c))return ({61:'小雨',63:'中雨',65:'大雨'})[c];if([66,67].includes(c))return '冻雨';if([71,73,75,77].includes(c))return '雪';if([80,81,82].includes(c))return '阵雨';if([85,86].includes(c))return '阵雪';if([95,96,99].includes(c))return '雷暴';return '天气代码 '+c}
function v12Hours(w){if(!w?.hourly)return [];const h=w.hourly;return h.time.map((t,i)=>({t,temp:h.temperature_2m?.[i],rain:h.precipitation?.[i],prob:h.precipitation_probability?.[i],weather:h.weather_code?.[i]})).filter(x=>x.t>=(w.current?.time||'')).slice(0,24)}
function v12Chart(rows,type){const temp=type==='temp',key=temp?'temp':'rain',values=rows.map(r=>r[key]).filter(Number.isFinite);if(!values.length)return `<p>${temp?'气温':'降水'}数据未取得。</p>`;let lo=temp?Math.floor(Math.min(...values)-1):0,hi=temp?Math.ceil(Math.max(...values)+1):Math.max(1,Math.ceil(Math.max(...values)));const x=i=>64+i*652/Math.max(1,rows.length-1),y=v=>220-(v-lo)/(hi-lo)*160;let grid='';for(let i=0;i<=4;i++){const val=lo+(hi-lo)*i/4,py=y(val);grid+=`<line x1="64" x2="724" y1="${py}" y2="${py}" stroke="#dce7e9"/><text x="54" y="${py+4}" text-anchor="end" font-size="12" fill="#617582">${Number(val.toFixed(2))}</text>`}const axis=`<path d="M64 60V220H730" fill="none" stroke="#8fa5ad"/><text x="12" y="34" font-size="13" fill="#435f6c">${temp?'气温（°C）':'小时降水量（mm）'}</text><text x="716" y="260" text-anchor="end" font-size="11" fill="#617582">时间（北京时间）</text>${rows.filter((r,i)=>i%4===0).map(r=>{const i=rows.indexOf(r);return `<text x="${x(i)}" y="240" text-anchor="middle" font-size="12" fill="#617582">${r.t.slice(5,10)+' '+r.t.slice(11,16)}</text>`}).join('')}`;
let marks='';if(temp){let path='',prev=false;rows.forEach((r,i)=>{if(!Number.isFinite(r.temp)){prev=false;return}path+=(prev?' L':' M')+x(i)+' '+y(r.temp);prev=true});marks=`<path d="${path}" stroke="#159b8e" stroke-width="3" fill="none"/>`+rows.map((r,i)=>!Number.isFinite(r.temp)?'':`<circle cx="${x(i)}" cy="${y(r.temp)}" r="3" fill="#159b8e"><title>${r.t}：${r.temp}°C；${v12WeatherName(r.weather)}</title></circle>${i%4===0?`<text x="${x(i)}" y="48" text-anchor="middle" font-size="11" fill="#4d6c79">${esc(v12WeatherName(r.weather))}</text>`:''}`).join('')}else{marks=rows.map((r,i)=>!Number.isFinite(r.rain)||r.rain===0?'':`<rect x="${x(i)-8}" y="${y(r.rain)}" width="16" height="${220-y(r.rain)}" fill="#4d82ed"><title>${r.t}：小时降水${r.rain}mm；降水概率${r.prob??'未取得'}%</title></rect>`).join('');if(values.every(v=>v===0))marks+='<text x="390" y="140" text-anchor="middle" font-size="14" fill="#617582">已取得的时段小时降水均为0 mm</text>'}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 276" font-family="Arial, Microsoft YaHei, Noto Sans CJK SC, sans-serif" role="img" aria-label="${temp?'逐小时气温与天气':'逐小时降水'}"><rect width="760" height="276" fill="white"/>${grid}${axis}${marks}</svg>`}
v5Trend=function(){if(V2.mode==='history')return '<div class="empty">没有当时连续观测或逐小时数值预报，不能用事后再分析生成未来天气图。</div>';const w=V2.weather,rows=v12Hours(w);if(!rows.length)return '<div class="empty">查询天气后显示未来24小时气温、天气与降水。</div>';return `<div class="v12charts v5chart"><div class="row"><b>未来24小时 · ${esc(w.place)}</b><small>模型天气，非站点实测</small></div><section><h3>气温与天气</h3>${v12Chart(rows,'temp')}</section><section><h3>降水趋势</h3>${v12Chart(rows,'rain')}<p class="muted">柱形表示该小时累计降水量；0表示模型该小时无降水，缺测显示“未取得”。天气图标与毫米雨量为模型代表预报，降水概率表示发生降水的可能性；两者统计含义不同，所以可出现“晴、0mm”与较高概率并列。它们均不表示积水或事故概率。</p></section><details><summary>查看逐小时数据表</summary><div class="tablewrap"><table><tr><th>时间（北京时间）</th><th>天气</th><th>气温（°C）</th><th>小时降水（mm）</th><th>降水概率（%）</th></tr>${rows.map(r=>`<tr><td>${esc(dateText(r.t))}</td><td>${esc(v12WeatherName(r.weather))}</td><td>${r.temp??'未取得'}</td><td>${r.rain??'未取得'}</td><td>${r.prob??'未取得'}</td></tr>`).join('')}</table></div></details></div>`};
const v12FeedbackBase=vFeedback;vFeedback=function(p){return v12FeedbackBase(p).filter(f=>!f.demo)};
const v12RelatedBase=vRelated;
vRelated=function(p){const old=v12RelatedBase(p),closures=(p?.segments||[]).map(g=>g.closure).filter(Boolean),routeMetro=p?.transport==='公共交通'&&p?.segments?.length;return [...new Map([...old.filter(e=>!routeMetro||e.category!=='暂停运营'),...closures].map(e=>[e.record_id,e])).values()].filter(e=>!p?.at||p.mode!=='history'||new Date(e.available_at||e.source_published_at)<=new Date(p.at+':00+08:00'))};
// Evidence matching is a textual candidate association, never verified route exposure.
function v12RiskMatches(p,r){const input=[p?.origin||V2.origin,...(p?.vias||V2.vias),p?.destination||V2.destination],roads=p?.roadNames||[],matches=[];for(const t of input.filter(Boolean)){const place=vResolve(t),name=place?.name||t,station=R10.stations.find(x=>x.name===name);const aliases=station?name==='罗湖'?['罗湖火车站','罗湖站','罗湖口岸']:name==='老街'?['老街地铁站','老街站']:name==='国贸'?['国贸站','国贸地铁站']:[name+'地铁站',name+'站']: [t,name];const hit=aliases.find(a=>r.risk_description.includes(a));if(hit)matches.push({term:t,hit,type:'地点名称匹配'});if(!station&&(name===r.street||name===r.street.replace('街道','')))matches.push({term:t,hit:r.street,type:'街道资料范围（不等于整条行程受影响）'})}for(const road of roads){if(road.length>=3&&r.risk_description.includes(road))matches.push({term:road,hit:road,type:'道路名称匹配（指引所列区段）'})}return matches}
vRisks=function(p){const mode=p?.mode||V2.mode,at=p?.at||V2.at,year=mode==='now'?2026:[2026,2025,2024,2023].find(y=>new Date((D.guide_dates[y]||`${y}-12-31`)+'T23:59:59+08:00')<=new Date(at+':00+08:00'));return D.risks.filter(r=>r.guide_year===year&&v12RiskMatches(p,r).length)};
const RISK_HELP='沿线积水概率未提供：目前缺少覆盖路线和时段的积水深度、道路通行观测，以及成对的历史预测与真实结果；也未训练、校准和验证概率模型。因此不能把雨量、长期隐患条数或规则等级换算成可靠百分比。未知不表示0%或安全。';
const HAZARD_HELP='长期隐患是官方街道防汛指引中列出的低洼、易积水地点或路段，是长期资料提示，不是当前实测积水。本站按地点或道路名称关联；地点名称关联到指引内容，详情列出原文中的位置与原因。';
function v12Help(label,body){return `<span class="v12help" tabindex="0" role="note" title="${esc(body)}" aria-label="${esc(label+'：'+body)}">${esc(label)}<span class="v12tooltip" role="tooltip">${esc(body)}</span></span>`}
function v12Hazards(p){const rs=vRisks(p);return rs.map(r=>`<div class="v12hazard"><b>${esc(r.street)} · ${r.guide_year}版防汛指引</b><p data-original>长期隐患：${typeof v17ExplainText==='function'?v17ExplainText(r.risk_description):esc(r.risk_description)}</p><small>关联理由：${v12RiskMatches(p,r).map(m=>`${esc(m.type)}，输入“${esc(m.term)}”关联“${esc(m.hit)}”`).join('；')}。关联范围以指引列出的地点及路段为准。</small><div>${vSource(r)}</div></div>`).join('')||'<p>现有防汛指引中暂无该地点或道路的专项记录。</p>'}
function v12EventText(e){if(/两个方向暂停运营/.test(e.summary))return e.summary.replace('该区段两个方向暂停运营。',`该区段两个方向暂停运营（${e.place_text}，往返两个方向均暂停地铁客运服务）。`);return e.summary}
// Risk summary is consolidated in v11.js; helpers below provide traceable detail.
