v5Risk=function(p){if(p?.blocked)return '当时公告涉及停运';if(vRelated(p).some(e=>/封闭/.test(e.category)))return '相关公告需核对';return vRisks(p).length?'资料关联：长期易积水（非当前实况）':vFeedback(p).length?'存在待核验线索':'风险未知'};
