const v12PartsBase=vExportParts;vExportParts=function(s,c){const ps=v12PartsBase(s,c);if(c.official){const item=ps.find(p=>p.title==='官方隐患与公告');if(item){for(const e of D.events)item.text=item.text.replaceAll(e.place_text+'：'+e.summary,e.place_text+'：'+v12EventText(e));item.text+='\n\n长期隐患关联说明：名称关联仅为候选依据，不代表已经核验路线与隐患点重合。'+s.plans.map(p=>vRisks(p).map(r=>'\n'+r.street+'：'+v12RiskMatches(p,r).map(m=>m.type+' '+m.term+' → '+m.hit).join('；')).join('')).join('')}}return ps};
