const labels=[],occupied=[],names=new Set();function label(lon,lat,text,color='#5c707a',strong=false){const px=x(lon),py=y(lat);if(px<58||px>840||py<65||py>365||names.has(text))return '';const width=Math.min(210,text.length*11),box={x:px-width/2,y:py-12,w:width,h:18};if(!strong&&occupied.some(q=>box.x<q.x+q.w+6&&box.x+box.w>q.x-6&&box.y<q.y+q.h+6&&box.y+box.h>q.y-6))return '';occupied.push(box);names.add(text);return `<text x="${px.toFixed(1)}" y="${py.toFixed(1)}" text-anchor="middle" font-size="${strong?12:10}" fill="${color}" style="paint-order:stroke;stroke:white;stroke-width:3px;stroke-linejoin:round">${esc(text)}</text>`}
