R10.stations.filter(m=>visible([m.lon,m.lat])).forEach(m=>labels.push(label(m.lon,m.lat,m.name+'站','#476987')));roads.filter(f=>f.name&&!['footway','path','steps','service'].includes(f.class)).sort((a,b)=>b.coordinates.length-a.coordinates.length).forEach(f=>{const c=f.coordinates[Math.floor(f.coordinates.length/2)];if(names.size<30)labels.push(label(c[0],c[1],f.name))});
